// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function testFuzz_property(address callee, bytes memory data) public {
        // Only route through an adversarial helper that actually reverts; an EOA would always succeed.
        Reverter r = new Reverter();
        callee = address(r);

        bool ok = true;
        bytes4 sel;
        try c.forward(callee, data) {
            ok = false;
        } catch (bytes memory reason) {
            if (reason.length >= 4) {
                sel = bytes4(reason);
            }
        }
        // Reference: a failing external call must revert with a plain Error, never a Panic(0x01).
        // Mutant: assert(_s) turns this same failure into Panic(0x01).
        assertTrue(ok && sel != bytes4(0x4e487b71));
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
